                    // `m14c_apfsds_vs_heavy.ron` emits zero
                    // `armor.heat_jet_traversed` /
                    // `armor.apfsds_long_rod_through` events at runtime
                    // (the M14C scrutiny gap).
                    if pressed {
                        state.pending_intent.ammo_kind = ammo_kind;
                    }
