    #[test]
    fn m8_speed_pct_75_skips_one_in_four_ticks_via_accumulator() {
        let mut acc: u16 = 0;
        let pct: u16 = 75;
        let mut advances = 0;
        let mut skips = 0;
        for _ in 0..4 {
            acc = acc.saturating_add(pct);
            if acc >= 100 {
                acc -= 100;
                advances += 1;
            } else {
                skips += 1;
            }
        }
        assert_eq!(advances, 3, "Slowdown75: 3 advances per 4 wall ticks");
        assert_eq!(skips, 1, "Slowdown75: 1 skip per 4 wall ticks");
    }

